mapper.sql:
WHERE r.deleted_at IS NULL AND r.category_code = #{query.category} AND r.business_status = 'OPERATING'
AND r.price_kind != 'UNKNOWN' AND r.price_per_person <= #{query.maxPrice}
AND () <= #{query.maxDistanceMeters}
AND () IN #{tier}
AND s.participant_count > 0 AND s.overall_score_sum >= 6.2 * s.participant_count
AND s.participant_count > 0 AND s.overall_score_sum < 5.0 * s.participant_count
AND (r.name LIKE #{query.keywordPattern} ESCAPE '!' OR r.address LIKE #{query.keywordPattern} ESCAPE '!' OR c.name LIKE #{query.keywordPattern} ESCAPE '!' OR EXISTS (SELECT 1 FROM restaurant_tags t WHERE t.restaurant_id = r.id AND t.tag LIKE #{query.keywordPattern} ESCAPE '!'))
